 29	        mapper.registerModule(new JavaTimeModule());
 30	        mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 31	
 32	        Javalin app = Javalin.create(config -> {
 33	            config.jsonMapper(new JsonMapper() {
 34	                @Override
 35	                public String toJsonString(Object obj, Type type) {
 36	                    try {
 37	                        return mapper.writeValueAsString(obj);
 38	                    } catch (Exception e) {
 39	                        throw new RuntimeException(e);
 40	                    }
 41	                }
 42	
 43	                @Override
 44	                public Object fromJsonString(String json, Type targetType) {
 45	                    try {
 46	                        return mapper.readValue(json, mapper.constructType(targetType));
 47	                    } catch (Exception e) {
 48	                        throw new RuntimeException(e);
 49	                    }
 50	                }
 51	            });
 52	        });
 53	
 54	        app.get("/rooms", ctx -> {
 55	            try {
 56	                List<Room> rooms = RoomRepository.findAll();
 57	                ctx.json(rooms);
 58	            } catch (SQLException e) {
 59	                ctx.status(500);
 60	                ctx.json(Map.of("error", "DATABASE_ERROR", "message", e.getMessage()));
 61	            }
 62	        });
 63	
 64	        app.post("/reservations", ctx -> {
 65	            try {
 66	                Map<String, Object> body = ctx.bodyAsClass(Map.class);
 67	
 68	                int roomNumber = ((Number) body.get("roomNumber")).intValue();
 69	                String guestName = (String) body.get("guestName");
 70	                String guestEmail = (String) body.get("guestEmail");
 71	                String guestCpf = (String) body.get("guestCpf");
 72	                LocalDate checkIn = LocalDate.parse((String) body.get("checkIn"));
 73	                LocalDate checkOut = LocalDate.parse((String) body.get("checkOut"));
 74	                int guests = ((Number) body.get("guests")).intValue();
 75	                String ratePlan = (String) body.get("ratePlan");
 76	
 77	                if (checkIn == null || checkOut == null) {
 78	                    ctx.status(400);
 79	                    ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid date format"));
 80	                    return;
 81	                }
 82	
 83	                Reservation created = ReservationService.create(
 84	                    roomNumber, guestName, guestEmail, guestCpf,
 85	                    checkIn, checkOut, guests, ratePlan
 86	                );
 87	
 88	                ctx.status(201);
 89	                ctx.json(created);
 90	            } catch (IllegalArgumentException e) {
 91	                String errorCode = e.getMessage();
 92	                if ("ROOM_NOT_FOUND".equals(errorCode)) {
 93	                    ctx.status(404);
 94	                } else if ("CAPACITY_EXCEEDED".equals(errorCode)) {
 95	                    ctx.status(422);
 96	                } else if ("ROOM_UNAVAILABLE".equals(errorCode)) {
 97	                    ctx.status(409);
 98	                } else {
 99	                    ctx.status(400);
100	                }
101	                ctx.json(Map.of("error", errorCode, "message", errorCode));
102	            } catch (Exception e) {
103	                ctx.status(400);
104	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
105	            }
106	        });
107	
108	        app.get("/reservations/{id}", ctx -> {
109	            try {
110	                long id = Long.parseLong(ctx.pathParam("id"));
111	                Reservation reservation = ReservationService.getById(id);
112	                ctx.json(reservation);
113	            } catch (IllegalArgumentException e) {
114	                ctx.status(404);
115	                ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
116	            } catch (SQLException e) {
117	                ctx.status(500);
118	                ctx.json(Map.of("error", "DATABASE_ERROR", "message", e.getMessage()));
119	            }
120	        });
