122	        app.post("/reservations/{id}/confirmation", ctx -> {
123	            try {
124	                long id = Long.parseLong(ctx.pathParam("id"));
125	                Reservation reservation = ReservationService.confirm(id);
126	
127	                Optional<Room> room = RoomRepository.findByNumber(reservation.roomNumber());
128	                if (room.isPresent()) {
129	                    MessageService.sendConfirmationEmail(reservation, room.get());
130	                }
131	
132	                ctx.json(reservation);
133	            } catch (IllegalArgumentException e) {
134	                String errorCode = e.getMessage();
135	                if ("RESERVATION_NOT_FOUND".equals(errorCode)) {
136	                    ctx.status(404);
137	                } else {
138	                    ctx.status(409);
139	                }
140	                ctx.json(Map.of("error", errorCode, "message", errorCode));
141	            } catch (SQLException e) {
142	                ctx.status(500);
143	                ctx.json(Map.of("error", "DATABASE_ERROR", "message", e.getMessage()));
144	            }
145	        });
146	
147	        app.post("/reservations/{id}/cancellation", ctx -> {
148	            try {
149	                long id = Long.parseLong(ctx.pathParam("id"));
150	                Reservation reservation = ReservationService.cancel(id);
151	                ctx.json(reservation);
152	            } catch (IllegalArgumentException e) {
153	                String errorCode = e.getMessage();
154	                if ("RESERVATION_NOT_FOUND".equals(errorCode)) {
155	                    ctx.status(404);
156	                } else {
157	                    ctx.status(409);
158	                }
159	                ctx.json(Map.of("error", errorCode, "message", errorCode));
160	            } catch (SQLException e) {
161	                ctx.status(500);
162	                ctx.json(Map.of("error", "DATABASE_ERROR", "message", e.getMessage()));
163	            }
164	        });
165	
166	        app.post("/reservations/{id}/check-in", ctx -> {
167	            try {
168	                long id = Long.parseLong(ctx.pathParam("id"));
169	                Reservation reservation = ReservationService.checkIn(id);
170	                ctx.json(reservation);
171	            } catch (IllegalArgumentException e) {
172	                String errorCode = e.getMessage();
173	                if ("RESERVATION_NOT_FOUND".equals(errorCode)) {
174	                    ctx.status(404);
175	                } else {
176	                    ctx.status(409);
177	                }
178	                ctx.json(Map.of("error", errorCode, "message", errorCode));
179	            } catch (SQLException e) {
180	                ctx.status(500);
181	                ctx.json(Map.of("error", "DATABASE_ERROR", "message", e.getMessage()));
182	            }
183	        });
184	
185	        app.post("/reservations/{id}/check-out", ctx -> {
186	            try {
187	                long id = Long.parseLong(ctx.pathParam("id"));
188	                Reservation reservation = ReservationService.checkOut(id);
189	
190	                Optional<Room> room = RoomRepository.findByNumber(reservation.roomNumber());
191	                if (room.isEmpty()) {
192	                    ctx.status(500);
193	                    ctx.json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
194	                    return;
195	                }
196	
197	                Receipt receipt = new Receipt(
198	                    "Comprovante de reserva",
199	                    reservation.id(),
200	                    reservation.guestName(),
201	                    reservation.guestCpf(),
