281	
282	        app.get("/reports/occupancy", ctx -> {
283	            try {
284	                String dateStr = ctx.queryParam("date");
285	                LocalDate date = LocalDate.parse(dateStr);
286	
287	                ReportGenerator report = new OccupancyReport(date);
288	                String csv = report.generate();
289	
290	                ctx.contentType("text/csv; charset=utf-8");
291	                ctx.result(csv);
292	            } catch (Exception e) {
293	                ctx.status(400);
294	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid date format"));
295	            }
296	        });
297	
298	        app.get("/reports/revenue", ctx -> {
299	            try {
300	                String monthStr = ctx.queryParam("month");
301	                YearMonth month = YearMonth.parse(monthStr);
302	
303	                ReportGenerator report = new RevenueReport(month);
304	                String csv = report.generate();
305	
306	                ctx.contentType("text/csv; charset=utf-8");
