313	
314	        app.get("/reports/tourism-tax", ctx -> {
315	            try {
316	                String monthStr = ctx.queryParam("month");
317	                YearMonth month = YearMonth.parse(monthStr);
318	
319	                ReportGenerator report = new TourismTaxReport(month);
