    10	
    11	public class ReservationService {
    12	    public static Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
    13	                                    LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan)
    14	            throws SQLException {
    15	
    16	        Optional<Room> room = RoomRepository.findByNumber(roomNumber);
    17	        if (room.isEmpty()) {
    18	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
    19	        }
    20	
    21	        if (guests < 1) {
    22	            throw new IllegalArgumentException("INVALID_REQUEST");
    23	        }
    24	
    25	        if (guests > room.get().capacity()) {
    26	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
    27	        }
    28	
    29	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
    30	            throw new IllegalArgumentException("INVALID_REQUEST");
    31	        }
    32	
    33	        if (!ReservationRepository.isRoomAvailable(roomNumber, checkIn, checkOut)) {
    34	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
    35	        }
    36	
    37	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    38	        double subtotal = PriceCalculator.calculateSubtotal(room.get().nightlyRate(), checkIn, checkOut);
    39	        double discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
    40	        double total = PriceCalculator.calculateTotal(subtotal, discount);
    41	
    42	        Reservation reservation = new Reservation(
    43	            0,
    44	            roomNumber,
    45	            guestName,
    46	            guestEmail,
    47	            guestCpf,
    48	            checkIn,
    49	            checkOut,
    50	            guests,
    51	            ratePlan,
    52	            nights,
    53	            subtotal,
    54	            discount,
    55	            total,
    56	            "PENDING",
    57	            0.0,
    58	            null
    59	        );
    60	
    61	        long id = ReservationRepository.create(reservation);
    62	        return new Reservation(id, roomNumber, guestName, guestEmail, guestCpf,
    63	            checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total,
    64	            "PENDING", 0.0, null);
    65	    }
    66	
    67	    public static Reservation getById(long id) throws SQLException {
    68	        Optional<Reservation> reservation = ReservationRepository.findById(id);
    69	        if (reservation.isEmpty()) {
    70	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
    71	        }
    72	        return reservation.get();
    73	    }
    74	
    75	    public static Reservation confirm(long id) throws SQLException {
    76	        Reservation reservation = getById(id);
    77	
    78	        if (!"PENDING".equals(reservation.status())) {
    79	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    80	        }
    81	
    82	        ReservationRepository.updateStatus(id, "CONFIRMED");
    83	        ReservationRepository.updateAmountPaid(id, reservation.total());
    84	
    85	        return reservation.withStatus("CONFIRMED").withAmountPaid(reservation.total());
    86	    }
    87	
    88	    public static Reservation checkIn(long id) throws SQLException {
    89	        Reservation reservation = getById(id);
    90	
    91	        if (!"CONFIRMED".equals(reservation.status())) {
    92	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    93	        }
    94	
    95	        ReservationRepository.updateStatus(id, "CHECKED_IN");
    96	        return reservation.withStatus("CHECKED_IN");
    97	    }
    98	
    99	    public static Reservation checkOut(long id) throws SQLException {
   100	        Reservation reservation = getById(id);
   101	
   102	        if (!"CHECKED_IN".equals(reservation.status())) {
   103	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   104	        }
   105	
   106	        ReservationRepository.updateStatus(id, "CHECKED_OUT");
   107	        return reservation.withStatus("CHECKED_OUT");
   108	    }
   109	
   110	    public static Reservation cancel(long id) throws SQLException {
   111	        Reservation reservation = getById(id);
   112	
   113	        if (!"PENDING".equals(reservation.status()) && !"CONFIRMED".equals(reservation.status())) {
   114	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   115	        }
   116	
   117	        Double refund = null;
   118	        if ("CONFIRMED".equals(reservation.status())) {
   119	            if ("STANDARD".equals(reservation.ratePlan())) {
   120	                refund = reservation.amountPaid();
   121	            } else {
   122	                refund = 0.0;
   123	            }
   124	        }
   125	
   126	        ReservationRepository.updateStatus(id, "CANCELLED");
   127	        if (refund != null) {
   128	            ReservationRepository.updateRefund(id, refund);
   129	        }
   130	
   131	        return reservation.withStatus("CANCELLED").withRefund(refund);
   132	    }
   133	}
