     5	public class Database {
     6	    private static final String ROOMS_TABLE = """
     7	        CREATE TABLE IF NOT EXISTS rooms (
     8	            number INTEGER PRIMARY KEY,
     9	            type VARCHAR(50) NOT NULL,
    10	            capacity INTEGER NOT NULL,
    11	            nightly_rate NUMERIC(10, 2) NOT NULL
    12	        )
    13	        """;
    14	
    15	    private static final String RESERVATIONS_TABLE = """
    16	        CREATE TABLE IF NOT EXISTS reservations (
    17	            id BIGSERIAL PRIMARY KEY,
    18	            room_number INTEGER NOT NULL REFERENCES rooms(number),
    19	            guest_name VARCHAR(255) NOT NULL,
    20	            guest_email VARCHAR(255) NOT NULL,
    21	            guest_cpf VARCHAR(11) NOT NULL,
    22	            check_in DATE NOT NULL,
    23	            check_out DATE NOT NULL,
    24	            guests INTEGER NOT NULL,
    25	            rate_plan VARCHAR(50) NOT NULL,
    26	            nights INTEGER NOT NULL,
    27	            subtotal NUMERIC(10, 2) NOT NULL,
    28	            discount NUMERIC(10, 2) NOT NULL,
    29	            total NUMERIC(10, 2) NOT NULL,
    30	            status VARCHAR(50) NOT NULL,
    31	            amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
    32	            refund NUMERIC(10, 2),
    33	            created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
    34	        )
    35	        """;
    36	
    37	    private static final String MESSAGES_TABLE = """
    38	        CREATE TABLE IF NOT EXISTS messages (
    39	            id BIGSERIAL PRIMARY KEY,
    40	            channel VARCHAR(50) NOT NULL,
    41	            to_email VARCHAR(255) NOT NULL,
    42	            subject VARCHAR(255) NOT NULL,
    43	            body TEXT NOT NULL,
    44	            created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
    45	        )
    46	        """;
    47	
    48	    private static Connection connection;
    49	
    50	    public static void initialize(String dbUrl, String dbUser, String dbPassword) throws SQLException {
    51	        connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
    52	        createTables();
    53	        initializeRooms();
    54	    }
    55	
    56	    private static void createTables() throws SQLException {
    57	        try (Statement stmt = connection.createStatement()) {
    58	            stmt.execute(ROOMS_TABLE);
    59	            stmt.execute(RESERVATIONS_TABLE);
    60	            stmt.execute(MESSAGES_TABLE);
    61	        }
    62	    }
    63	
    64	    private static void initializeRooms() throws SQLException {
    65	        String checkSql = "SELECT COUNT(*) FROM rooms";
    66	        try (Statement stmt = connection.createStatement();
    67	             ResultSet rs = stmt.executeQuery(checkSql)) {
    68	            rs.next();
    69	            if (rs.getInt(1) == 0) {
    70	                String insertSql = """
    71	                    INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
    72	                    (101, 'STANDARD', 2, 249.90),
    73	                    (102, 'STANDARD', 2, 249.90),
    74	                    (201, 'DELUXE', 3, 389.90),
    75	                    (202, 'DELUXE', 3, 389.90),
    76	                    (301, 'SUITE', 4, 579.90)
    77	                    """;
    78	                try (Statement insertStmt = connection.createStatement()) {
    79	                    insertStmt.execute(insertSql);
    80	                }
    81	            }
    82	        }
    83	    }
    84	
    85	    public static Connection getConnection() {
    86	        return connection;
    87	    }
    88	
    89	    public static void close() throws SQLException {
    90	        if (connection != null && !connection.isClosed()) {
    91	            connection.close();
    92	        }
    93	    }
    94	}
