    13	                                    LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan)
    14	            throws SQLException {
    15	
    16	        Optional<Room> room = RoomRepository.findByNumber(roomNumber);
    17	        if (room.isEmpty()) {
    18	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
    19	        }
    20	
    21	        if (guests < 1) {
    22	            throw new IllegalArgumentException("INVALID_REQUEST");
    23	        }
    24	
    25	        if (guests > room.get().capacity()) {
    26	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
    27	        }
    28	
    29	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
    30	            throw new IllegalArgumentException("INVALID_REQUEST");
    31	        }
    32	
    33	        if (!ReservationRepository.isRoomAvailable(roomNumber, checkIn, checkOut)) {
    34	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
    35	        }
    36	
    37	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    38	        double subtotal = PriceCalculator.calculateSubtotal(room.get().nightlyRate(), checkIn, checkOut);
    39	        double discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
    40	        double total = PriceCalculator.calculateTotal(subtotal, discount);
