     1	package com.pousadamareaalta.util;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public class PriceCalculator {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.2");
    10	    private static final BigDecimal DISCOUNT_RATE = new BigDecimal("0.15");
    11	
    12	    public static boolean isHighSeason(LocalDate date) {
    13	        Month month = date.getMonth();
    14	        int dayOfMonth = date.getDayOfMonth();
    15	
    16	        if (month == Month.JULY) {
    17	            return true;
    18	        }
    19	        if (month == Month.DECEMBER) {
    20	            return dayOfMonth >= 15;
    21	        }
    22	        if (month == Month.JANUARY) {
    23	            return true;
    24	        }
    25	        if (month == Month.FEBRUARY) {
    26	            return dayOfMonth <= 28;
    27	        }
    28	        return false;
    29	    }
    30	
    31	    public static double calculateNightlyPrice(double nightlyRate, LocalDate date) {
    32	        BigDecimal rate = new BigDecimal(String.format("%.2f", nightlyRate));
    33	        BigDecimal price = isHighSeason(date) ? rate.multiply(HIGH_SEASON_MULTIPLIER) : rate;
    34	        return price.setScale(2, RoundingMode.HALF_EVEN).doubleValue();
    35	    }
    36	
    37	    public static double calculateSubtotal(double nightlyRate, LocalDate checkIn, LocalDate checkOut) {
    38	        BigDecimal subtotal = BigDecimal.ZERO;
    39	        LocalDate current = checkIn;
    40	
    41	        while (current.isBefore(checkOut)) {
    42	            double nightPrice = calculateNightlyPrice(nightlyRate, current);
    43	            subtotal = subtotal.add(new BigDecimal(String.format("%.2f", nightPrice)));
    44	            current = current.plusDays(1);
    45	        }
    46	
    47	        return subtotal.setScale(2, RoundingMode.HALF_EVEN).doubleValue();
    48	    }
    49	
    50	    public static double calculateDiscount(double subtotal, String ratePlan) {
    51	        if ("NON_REFUNDABLE".equals(ratePlan)) {
    52	            BigDecimal sub = new BigDecimal(String.format("%.2f", subtotal));
    53	            BigDecimal discount = sub.multiply(DISCOUNT_RATE).setScale(2, RoundingMode.HALF_EVEN);
    54	            return discount.doubleValue();
    55	        }
    56	        return 0.0;
    57	    }
    58	
    59	    public static double calculateTotal(double subtotal, double discount) {
    60	        BigDecimal sub = new BigDecimal(String.format("%.2f", subtotal));
    61	        BigDecimal disc = new BigDecimal(String.format("%.2f", discount));
    62	        return sub.subtract(disc).setScale(2, RoundingMode.HALF_EVEN).doubleValue();
    63	    }
    64	}
